   (clk,
    rx_clk_in_p,
    rx_clk_in_n);
  output clk;
  input rx_clk_in_p;
  input rx_clk_in_n;

  wire clk;
  wire clk_ibuf_s;
  wire rx_clk_in_n;
  wire rx_clk_in_p;

  (* BOX_TYPE = "PRIMITIVE" *) 
  BUFG i_clk_gbuf
       (.I(clk_ibuf_s),
        .O(clk));
  (* BOX_TYPE = "PRIMITIVE" *) 
  (* CAPACITANCE = "DONT_CARE" *) 
  (* IBUF_DELAY_VALUE = "0" *) 
  (* XILINX_LEGACY_PRIM = "IBUFGDS" *) 
  IBUFDS #(
    .IOSTANDARD("DEFAULT")) 
    i_rx_clk_ibuf
       (.I(rx_clk_in_p),
        .IB(rx_clk_in_n),
        .O(clk_ibuf_s));
endmodule

